/* Purview Gurukul — Specialties: the Vision care track.
   Built from Purview’s "Vision care RCM: a simple guide for freshers" (internal, October 2026),
   with the code definitions checked against CPT, HCPCS Level II, ICD-10-CM and Medicare.gov,
   and with links to the VEC playbook and the vision denials in the library where they apply.
   Loaded after specialties.js; it adds one track to SPEC_TRACKS and its questions to SPEC_QUIZ. */
"use strict";
(function(){
if(typeof SPEC_TRACKS==="undefined"||typeof SPEC_QUIZ==="undefined") return;

const SRC="Vision care RCM: a simple guide for freshers (Purview, October 2026, internal), with code definitions checked against CPT, HCPCS and Medicare.gov.";

SPEC_TRACKS.push(
{id:"vision",name:"Vision care",short:"Vision",updated:"Vision care guide, October 2026",
 truth:"The guide is the starting point; the client’s playbook and the payer’s manual decide any rule on a claim.",
 blurb:"Eye care is the first specialty track. It gives the basic understanding a biller needs to work vision claims: what happens at an eye visit, the codes on the claim, which plan pays (the vision plan or the medical plan), and the denials that come up most. It is not a clinical course; it stops where the doctor’s work begins. Purview’s eye care client, VEC, has its own playbook under Purview SOPs; this track is the background that playbook assumes.",
 modules:[
{id:"vis-a",short:"Vision basics",title:"The eye visit",blurb:"Who does what in eye care, the four services at an eye visit, and the vision problems glasses correct.",lessons:[
 {id:"vis-who",title:"Who’s who in eye care: optometrist, ophthalmologist, optician",
  keywords:["optometrist","optometry","ophthalmologist","ophthalmology","optician","od vs md","eye doctor","who is an optometrist","difference between optometrist and ophthalmologist","vision specialty","eye care specialty","three o's","vision panel","eye care providers"],
  line:"Three kinds of eye professionals, three jobs: the optometrist (OD) examines eyes and prescribes glasses and contacts, the ophthalmologist (MD or DO) treats eye disease and operates, and the optician makes and fits the glasses. Most vision claims come from optometrists.",
  body:[
   "**Optometrist (OD).** A Doctor of Optometry: four years of optometry school after college. Think of the family eye doctor: eye exams, prescriptions for glasses and contact lenses, and treatment of common problems such as dry eye, pink eye and nearsightedness. Most routine vision claims, and most of the claims Purview works for eye care clients, come from optometrists.",
   "**Ophthalmologist (MD or DO).** A medical doctor who went to medical school and then trained for several more years in eye disease and eye surgery. The eye specialist: cataract surgery, glaucoma treatment, LASIK, retinal repair, injections for macular degeneration. Their claims look more like other medical claims: office visits, tests and procedures, billed to medical insurance.",
   "**Optician.** Not a doctor. The optician fills the prescription: helps the patient choose frames, measures the fit, orders the lenses from the lab and adjusts the finished glasses. In billing terms the optician’s work is the **materials** side: frames, lenses and contact lenses.",
   "**Why it matters for a claim.** The provider type decides what can be billed and to which plan. An optometrist’s routine exam goes to the vision plan; an ophthalmologist’s cataract visit goes to medical insurance. The rendering provider’s NPI and taxonomy on the claim must match who really saw the patient, and the provider must be on the vision plan’s panel (its network) for the plan to pay."
  ],
  compare:{title:"The three O’s",head:["","Optometrist (OD)","Ophthalmologist (MD/DO)","Optician"],rows:[
   ["What they do","Eye exams, glasses and contact lens prescriptions, common eye problems","Eye disease, surgery, injections, complex cases","Fits and dispenses glasses and contacts from the prescription"],
   ["Training","4-year optometry degree after college","Medical school, then years of hospital training in eye care","Technical training or certification; not a doctor"],
   ["Typical claims","Routine exam, refraction, CL fitting, materials","Office visits, tests, surgery, injections","Materials only: frames, lenses, contacts"],
   ["Usual payer","Vision plan, or the medical plan for a medical problem","Medical insurance (Medicare, commercial, Medicaid)","Vision plan materials benefit, or the patient"]]},
  terms:[["Optometrist (OD)","Doctor of Optometry: everyday eye care and vision correction, no surgery."],["Ophthalmologist","Medical doctor for eye disease and surgery."],["Optician","Fits and sells glasses and contacts from a prescription; not a doctor."],["Panel (vision plan network)","A vision plan’s network of providers. A provider not on the panel is out of network for that plan."]],
  tips:["On a claim, the rendering provider is the optometrist or ophthalmologist who saw the patient, never the optician.","Vision plans credential providers separately from medical plans. A doctor in network with Blue Cross may still be off the VSP panel; check both before the visit."],
  remember:"OD examines and prescribes. MD operates. Optician dispenses. The exam and the glasses are two different things, and they bill differently.",
  source:SRC},
 {id:"vis-journey",title:"The eye visit: exam, refraction, contact lens, CL fitting",
  keywords:["eye exam","what is refraction","refraction","what is cl","cl fitting","contact lens fitting","what is cl fitting","patient journey eye clinic","eye visit","what happens at an eye exam","dispensary","dispensing","shoe analogy","exam refraction cl cl fitting"],
  line:"Four things can happen at an eye visit, and each is billed on its own: the exam checks the eyes, the refraction finds the prescription, the contact lens evaluation chooses a lens, and the CL fitting makes sure it fits. The glasses or lenses handed over at the end are the materials.",
  flow:{steps:["**Exam**: the doctor checks eye health and vision","**Refraction**: the doctor finds the exact power the patient needs, for example right eye −2.00, left eye −1.50","**Contact lens (CL)**: if the patient wants contacts instead of glasses, the doctor evaluates the eyes and chooses a lens type","**CL fitting**: the doctor checks the lens sits in the right position, is comfortable, gives clear vision and moves properly when the patient blinks","**Dispensing**: the glasses or lenses are made and handed to the patient (the materials)"],to:"The codes on the vision claim"},
  body:[
   "**The simple story.** A patient walks in because they cannot see clearly. The doctor checks the eyes: that is the **exam**. The doctor finds the exact number the patient needs for clear vision: that is **refraction**. If the patient wants contact lenses rather than glasses, the doctor evaluates the eyes and chooses a lens: that is **CL** (contact lens). The doctor then makes sure the lens sits comfortably and gives clear vision: that is **CL fitting**.",
   "**The shoe shop.** The shop checks your foot size: the exam. It tells you exactly which size fits: refraction. You want a special kind of shoe: choosing CL. It makes sure the shoe is comfortable when you walk: CL fitting. Four steps, and a shop charges for the fitting and the shoe separately. So does an eye clinic.",
   "**Each service is its own line on the claim.** The exam has an exam code, the refraction is 92015, the contact lens fitting has its own code, and the materials have HCPCS codes. Each can carry its own copay or benefit, and each can be denied on its own. A visit can also have an exam without a refraction (a medical problem visit) or a CL fitting without a new exam (a follow-up fit): bill what the chart shows, not what the visit type usually has.",
   "**Dispensary.** The part of the clinic where finished glasses or lenses are handed to the patient. Dispensing is where the product is delivered, and where the materials side of the claim comes from."
  ],
  compare:{title:"Quick cheat sheet",head:["Term","Simple meaning","On the claim"],rows:[["Exam","The doctor checks the patient’s eyes","An exam code: 92002–92014, S0620/S0621 or an E/M code"],["Refraction","Finds the patient’s glasses or lens prescription","92015, on its own line"],["CL","Contact lens: evaluating the eyes for contacts","Part of the contact lens service"],["CL fitting","Checks whether the contact lens fits properly","92310–92313 (92071, 92072 for medical fits)"],["Dispensing","Glasses or lenses handed over","Materials: HCPCS V codes"]]},
  terms:[["Exam","The doctor’s check of eye health and vision."],["Refraction","The test that finds the lens power the patient needs. Its result is the prescription."],["Contact lens fitting","Making sure a chosen contact lens sits, feels and sees right. Billed separately from the exam."],["Dispensary","Where the finished glasses or contact lenses are handed to the patient."]],
  tips:["One-line memory trick: Exam → check. Refraction → prescription. CL → contact lens. CL fitting → proper fit.","When a vision claim has only an exam line, ask whether a refraction was done and left off: it is the line most often forgotten, and the one most often denied."],
  remember:"Exam → check. Refraction → prescription. CL → contact lens. CL fitting → proper fit. Four services, four lines.",
  source:SRC},
 {id:"vis-refractive",title:"Near and far: myopia, hyperopia, astigmatism and presbyopia",
  keywords:["myopia","hyperopia","metropia","hypermetropia","nearsighted","farsighted","near sighted","far sighted","astigmatism","presbyopia","refractive error","minus lens","plus lens","od os ou","what is od and os","sphere cylinder axis","pupillary distance","pd","reading a prescription","emmetropia"],
  line:"A refractive error means the eye does not focus light exactly on the retina. Myopia (nearsighted) is corrected with a minus lens, hyperopia (farsighted) with a plus lens, astigmatism with a cylinder, and presbyopia (age) with reading power or multifocals. On a claim these are the H52 diagnosis codes.",
  body:[
   "**Myopia, nearsightedness.** Close things are clear, far things are blurry: light focuses in front of the retina. Corrected with a **minus** lens (for example −2.00). Memory trick: My-opia, my close vision is fine, far is blurry.",
   "**Hyperopia, farsightedness** (also called hypermetropia). Far things are clearer than near: light focuses behind the retina. Corrected with a **plus** lens (for example +2.00), like reading glasses that pull the image forward. Normal vision with no error is called emmetropia.",
   "**Astigmatism.** The cornea is curved unevenly, more like a rugby ball than a football, so vision is blurred at every distance. Corrected with a **cylinder** power and an axis on the prescription, or a **toric** contact lens.",
   "**Presbyopia.** With age, from about 40, the lens inside the eye stiffens and near focus fades. Corrected with reading glasses, bifocals, progressives or **multifocal** contact lenses.",
   "**Reading a prescription.** OD is the right eye, OS the left, OU both. Sphere (SPH) is the main power, minus or plus. Cylinder (CYL) and axis correct astigmatism. ADD is the extra near power for presbyopia. PD, the pupillary distance, is the measurement between the pupils that the optician uses to centre the lenses."
  ],
  compare:{title:"The four refractive errors",head:["","Myopia (nearsighted)","Hyperopia (farsighted)","Astigmatism","Presbyopia"],rows:[
   ["Simple meaning","Sees near clearly, far is blurry","Sees far more clearly, near is blurry","Blurry at all distances","Near focus fades with age"],
   ["What happens","Light focuses in front of the retina","Light focuses behind the retina","Uneven curve of the cornea or lens","The eye’s lens loses flexibility"],
   ["Lens used","Minus power (−2.00)","Plus power (+2.00)","Cylinder and axis; toric contacts","Reading add; bifocal, progressive or multifocal"],
   ["ICD-10","H52.1-","H52.0-","H52.2-","H52.4"]]},
  terms:[["Refractive error","The eye does not focus light on the retina, so vision is blurred. The H52 family of diagnosis codes."],["Retina","The light-sensing layer at the back of the eye."],["Toric lens","A contact lens or spectacle lens that corrects astigmatism."],["Multifocal","A lens with more than one power, for presbyopia."],["OD / OS / OU","Right eye, left eye, both eyes."]],
  tips:["A plain refractive error (H52) with a routine exam is a vision plan claim. The same patient with a medical finding (cataract, glaucoma, diabetic changes) is a medical claim.","Minus for myopia, plus for hyperopia. A materials claim with +2.00 lenses and a myopia diagnosis does not add up: ask before you send it."],
  remember:"Myopia = minus = near is fine. Hyperopia = plus = far is fine. Astigmatism = cylinder. Presbyopia = age = add.",
  source:SRC}
]},
{id:"vis-b",short:"Vision codes",title:"The codes on a vision claim",blurb:"Exam codes, contact lens fitting codes, the HCPCS V codes for materials, and the eye diagnoses that decide which plan pays.",lessons:[
 {id:"vis-cpt-exam",title:"Exam codes: 92002–92014, S0620/S0621 and E/M",
  keywords:["92002","92004","92012","92014","92015","s0620","s0621","eye exam codes","exam codes vision","comprehensive eye exam code","intermediate eye exam","refraction code","refraction cpt","is refraction covered by medicare","routine eye exam code","ophthalmological services codes","e/m vs eye codes","eye codes","new patient eye exam","established patient eye exam"],
  line:"Eye exams are billed with the ophthalmological codes 92002–92014 (new or established patient, intermediate or comprehensive), with the routine codes S0620/S0621 on many vision plans, or with an office visit E/M code (99202–99215) for a medical problem. Refraction is always 92015 on its own line, and Medicare does not cover it.",
  body:[
   "**The four eye codes.** 92002 is a new patient, intermediate exam; 92004 a new patient, comprehensive exam; 92012 an established patient, intermediate exam; 92014 an established patient, comprehensive exam. Intermediate means a problem-focused check of part of the eye; comprehensive means the whole visual system, which may take more than one visit to complete.",
   "**New or established.** The same rule as everywhere in RCM: a patient who received professional services from the practice (same specialty, same group) within the past three years is established. A new-patient code for an established patient is a common vision denial or downcode.",
   "**S0620 and S0621.** HCPCS codes for a routine eye exam that **includes the refraction**: S0620 for a new patient, S0621 for an established one. Many vision plans, and some Medicaid and commercial plans, want these for routine visits. Medicare never pays S codes. Because the refraction is inside the S code, 92015 is not billed with it.",
   "**E/M codes.** When the visit is about a medical problem (red eye, pain, a diabetic check, follow-up of glaucoma), the doctor may bill an office visit code (99202–99215) instead of an eye code. Either set can be used for a medical visit; the chart and the payer’s policy decide. Never both for the same visit.",
   "**92015, refraction.** The test that finds the prescription. Billed on its own line, and known for one thing: **Original Medicare does not cover it**, and many medical plans treat it as routine. The patient pays it, or the vision plan does."
  ],
  compare:{title:"Exam codes at a glance",head:["Code","What it is","Patient"],rows:[["92002","Intermediate eye exam","New"],["92004","Comprehensive eye exam","New"],["92012","Intermediate eye exam","Established"],["92014","Comprehensive eye exam","Established"],["92015","Refraction (finding the prescription)","Any"],["S0620","Routine eye exam including refraction","New"],["S0621","Routine eye exam including refraction","Established"],["99202–99215","Office visit (E/M) for a medical eye problem","New / established"]]},
  terms:[["Intermediate exam","A problem-focused eye exam: history, a check of the part of the eye in question, and a plan."],["Comprehensive exam","A full evaluation of the whole visual system, which can span more than one visit."],["S codes","HCPCS Level II codes starting with S, used by commercial and Medicaid plans, never by Medicare."],["92015","Refraction. Medicare does not cover it; it is patient responsibility or a vision plan benefit."]],
  tips:["Same patient, same practice, within three years: established. 92004 billed for a patient seen last year denies or gets downcoded to 92014.","A vision plan that wants S0621 will deny 92014 for the same routine visit, and the other way round. The plan’s billing guide decides which code set it takes.","Never bill 92015 with S0620/S0621: the refraction is already inside the S code."],
  remember:"9200x new, 9201x established; 2 intermediate, 4 comprehensive. S0620/S0621 routine with refraction. 92015 refraction on its own, and Medicare says no.",
  see:[["basics","patient-terms"],["denial","Vision benefit not eligible: exam or materials"]],
  source:SRC},
 {id:"vis-cl-codes",title:"Contact lens fitting codes: 92310 and the special fits",
  keywords:["92310","92311","92312","92313","92071","92072","s0592","contact lens fitting code","cl fitting code","contact lens code","keratoconus","aphakia","scleral lens","corneoscleral","bandage lens","toric fitting","multifocal fitting","monovision","v2500","v2520","v2521","contact lens materials","fitting fee"],
  line:"A contact lens fitting is a separate service from the exam, billed with 92310 (both eyes, the standard fit) or its cousins: 92311/92312 for aphakia, 92313 for a corneoscleral lens, 92071 for a bandage lens on a diseased surface and 92072 for keratoconus. The lenses themselves are materials, billed with V25xx codes.",
  body:[
   "**92310** is the everyday code: prescribing and fitting corneal contact lenses for both eyes, for a patient who does not have aphakia. It covers the measurements, trial lenses and the checks until the prescription is final. If only one eye is fitted, report it with modifier 52 (reduced service) rather than RT or LT.",
   "**Aphakia and special lenses.** 92311 and 92312 are the fitting codes for one or both eyes with aphakia (no natural lens, usually after cataract surgery without an implant). 92313 is a corneoscleral (scleral) lens, which vaults over the cornea and rests on the white of the eye. These codes depend on the diagnosis: 92311 with a plain myopia diagnosis will deny.",
   "**Medical fits.** 92071 is fitting a contact lens to treat ocular surface disease (a bandage lens for a damaged cornea), and 92072 is the initial fitting for keratoconus, whatever lens type is used. These are medical services, billed to medical insurance with the medical diagnosis (keratoconus is H18.6-). Later keratoconus visits use the ordinary exam or E/M codes.",
   "**Fitting versus materials.** The fitting is the doctor’s professional work. The lenses are materials: V2500–V2599 for contact lenses by type (V2500 PMMA spherical, V2520 hydrophilic spherical, V2521 hydrophilic toric, V2523 hydrophilic extended wear, and so on), billed per lens. Vision plans usually have a separate contact lens allowance, and many cover the fitting fee only when contacts are chosen instead of glasses.",
   "**Specialty fits** such as toric (astigmatism), multifocal (presbyopia), monovision (one eye set for distance, the other for near), keratoconus and post-LASIK fittings take more work and more visits. Plans may pay a higher fitting fee for them, or treat the difference as the patient’s; the plan’s benefit summary says which. Some vision plans use S0592, a comprehensive contact lens evaluation, instead of the CPT fitting codes."
  ],
  compare:{title:"Contact lens codes",head:["Code","Use"],rows:[["92310","Fitting of corneal contact lenses, both eyes, no aphakia (the standard fit)"],["92311 / 92312","Fitting for aphakia, one eye / both eyes"],["92313","Corneoscleral (scleral) lens fitting"],["92071","Fitting a contact lens to treat ocular surface disease (bandage lens)"],["92072","Initial fitting for keratoconus"],["S0592","Comprehensive contact lens evaluation (some vision plans)"],["V2500–V2599","The contact lenses themselves, per lens (materials)"]]},
  terms:[["Aphakia","An eye with no natural lens, usually after cataract surgery without an implant."],["Keratoconus","A cornea that thins and bulges into a cone; needs specialty lenses (H18.6-)."],["Corneoscleral / scleral lens","A large lens that rests on the white of the eye and vaults over the cornea."],["Bandage lens","A soft lens placed to protect a damaged corneal surface while it heals."],["Toric / multifocal / monovision","An astigmatism lens; a lens with more than one power; one eye for distance and one for near."]],
  tips:["Fitting fee and lenses are two different lines, often two different benefits. A plan can pay the fitting and still deny the lenses, or the other way round.","Check the diagnosis before the code: 92310 with keratoconus, or 92311 without aphakia, is a coding error that denies."],
  remember:"92310 = the standard fit, both eyes. 923xx by diagnosis. 92071/92072 are medical fits. V25xx are the lenses.",
  source:SRC},
 {id:"vis-materials",title:"Materials: HCPCS V codes for frames, lenses and coatings",
  keywords:["v codes","v code","v2020","v2025","v2100","v2200","v2300","v2744","v2750","v2755","v2760","v2781","v2784","frames code","frame code","lens codes","materials claim","what is materials","exam vs material","two baskets","anti reflective coating","ar coating","photochromic","photochromatic","progressive lens","polycarbonate","bifocal","trifocal","single vision","overage","frame allowance","blue light","frame types","acetate frame","rimless","low vision aid","post cataract glasses","dme mac glasses"],
  line:"Glasses and contact lenses are materials, billed with HCPCS V codes: V2020 for a frame, V21xx/V22xx/V23xx for single vision, bifocal and trifocal lenses per lens, V25xx for contact lenses, and add-on codes for features such as V2750 anti-reflective, V2744 photochromic, V2781 progressive and V2784 polycarbonate. The plan pays its allowance; the patient pays the overage.",
  body:[
   "**Two baskets.** The exam is the doctor’s professional service, billed with CPT codes. The glasses or contacts are a product, billed with HCPCS codes. Plans pay the two differently (an exam copay versus a materials allowance), so a vision claim keeps them apart, often as two claims. Billing them apart also keeps the claim clean on audit.",
   "**Frames and lenses.** V2020 is a standard frame (V2025 a deluxe frame). Lenses are coded per lens, by type and power range: V2100–V2199 single vision, V2200–V2299 bifocal, V2300–V2399 trifocal. A pair of single-vision lenses is two units of the lens code, one per eye.",
   "**Features and coatings** are separate add-on codes, also per lens: V2750 anti-reflective coating, V2755 UV coating, V2744 photochromic tint (the lens darkens in sunlight), V2745 other tint, V2760 scratch-resistant coating, V2781 progressive lens, V2784 polycarbonate (thin and impact-resistant, used for children and safety). Most plans cover the basic lens and let the patient pay the extras, or give a fixed allowance toward them.",
   "**Contact lenses** are V2500–V2599, per lens, by material and design. The fitting fee is CPT (the previous topic); the lenses are V codes.",
   "**Frames.** PD (pupillary distance) is a measurement, not a code: the optician measures it so the lenses are centred on the eyes. Frame materials are acetate (a plant-based plastic), metal (titanium, steel) and rimless or semi-rimless styles with little or no visible frame; the plan’s frame allowance applies whatever the material, and a frame chosen for style is still one unit of V2020.",
   "**Patient overage.** A vision plan pays up to its allowance (for example $150 toward frames). The patient pays the rest, called the overage, plus any copay. Never bill the plan’s write-off to the patient, but do bill the overage: it is the patient’s by the plan’s own rules.",
   "**Medicare’s one exception.** Original Medicare does not cover ordinary glasses or contacts, with one exception: one pair of glasses or contact lenses after cataract surgery with an implanted lens. That claim goes to the DME MAC with the V codes, not to the Part B carrier; the patient pays 20% after the deductible. Low vision aids (V2600–V2615) and prosthetic eyes (V2623–V2629) exist too, but you will rarely see them."
  ],
  compare:{title:"Lens features",head:["Feature","Simple meaning","HCPCS"],rows:[["Single vision","One power: near or far","V21xx, per lens"],["Bifocal","Two powers in one lens: far and near","V22xx, per lens"],["Trifocal","Three powers in one lens","V23xx, per lens"],["Progressive","Bifocal or trifocal with no visible line","V2781 (add-on, per lens)"],["Anti-reflective (AR) coating","Cuts glare","V2750"],["UV coating","Blocks ultraviolet light","V2755"],["Photochromic","Darkens in sunlight, lightens indoors","V2744"],["Polycarbonate","Thin, impact-resistant lens","V2784"],["Blue light filter","Filters blue light from screens; usually not covered","Plan-specific, often patient-paid"]]},
  terms:[["Materials (vision)","Frames, lenses and contact lenses: the products, billed with HCPCS V codes."],["Materials allowance","The most a vision plan pays toward frames or contacts in a benefit period; the patient pays the overage."],["Overage","The part of the materials price above the plan’s allowance: patient responsibility."],["Per lens","Lens codes are billed per lens: two units for a pair."],["PD (pupillary distance)","The distance between the pupils, measured so the lenses are centred; a measurement, not a code."]],
  tips:["Count the units: a pair of lenses is 2, a frame is 1. Two frames on one claim is a duplicate waiting to happen.","Post-cataract glasses for a Medicare patient go to the DME MAC. Sent to the Part B carrier, they deny as not covered."],
  remember:"Exam = CPT. Materials = V codes, per lens. The plan pays the allowance; the patient pays the overage.",
  source:SRC},
 {id:"vis-icd",title:"ICD-10 for eyes: routine Z codes, H52 refractive errors and the medical diagnoses",
  keywords:["icd-10 eye","icd 10 eye codes","eye diagnosis codes","z01.00","z01.01","z dx","zdx","z diagnosis","h52","h52.1","h52.0","h25","h40","e11.3","cataract code","glaucoma code","diabetic retinopathy code","dry eye code","pink eye code","conjunctivitis code","laterality","chapter 7 icd","why the doctor did it","diagnosis vision claim","routine diagnosis"],
  line:"The diagnosis says why the visit happened, and in vision it decides which plan pays. Z01.00/Z01.01 is a routine eye exam and H52 a refractive error (both vision plan business), while cataract (H25–H26), glaucoma (H40), diabetic eye disease (E11.3-) and infections are medical diagnoses for the medical plan.",
  body:[
   "**CPT says what, ICD-10 says why.** Every claim needs both, and they must agree. A comprehensive exam with a routine diagnosis is a vision claim; the same exam with glaucoma is a medical claim. The diagnosis the doctor documents, not the plan the patient prefers, decides.",
   "**Routine codes.** Z01.00 is an encounter for examination of eyes and vision without abnormal findings; Z01.01 is the same with abnormal findings. Together with the H52 refractive errors (H52.0- hyperopia, H52.1- myopia, H52.2- astigmatism, H52.4 presbyopia) they mark a routine vision visit. Medical plans usually deny them as routine or non-covered: that is the **Z dx** denial.",
   "**Medical diagnoses.** Chapter 7 of ICD-10-CM (H00–H59) covers the eye. Common ones on claims: cataract H25.- (age-related) and H26.-, glaucoma H40.-, dry eye H04.12-, conjunctivitis (pink eye) H10.-, keratoconus H18.6-, macular degeneration H35.3-, retinal detachment H33.-. Diabetic eye disease sits in the diabetes chapter: E11.3- (type 2 diabetes with eye complications), E10.3- for type 1. These go to medical insurance, even at an optometrist.",
   "**Laterality.** Many eye codes end in a character for the side: 1 right, 2 left, 3 both eyes (for example H25.13, age-related nuclear cataract, bilateral). An unspecified side when the chart names the eye is a common reason for a coding query.",
   "**Also in the chapter.** Blindness and low vision are H54.-, the visual disturbances H53.- (amblyopia, lazy eye, is H53.0-), and strabismus (squint) is H49–H51."
  ],
  compare:{title:"Diagnosis families",head:["Family","Codes","Which plan"],rows:[["Routine eye exam","Z01.00, Z01.01","Vision plan"],["Refractive errors","H52.0- hyperopia, H52.1- myopia, H52.2- astigmatism, H52.4 presbyopia","Vision plan"],["Cataract","H25.-, H26.-","Medical"],["Glaucoma","H40.-","Medical"],["Diabetic eye disease","E11.3- (type 2), E10.3- (type 1)","Medical"],["Dry eye, pink eye","H04.12-, H10.-","Medical"],["Keratoconus","H18.6-","Medical"],["Macular degeneration","H35.3-","Medical"],["Blindness and low vision","H54.-","Medical"]]},
  terms:[["Z01.00 / Z01.01","Routine eye and vision exam, without / with abnormal findings."],["H52","Disorders of refraction: myopia, hyperopia, astigmatism, presbyopia."],["Laterality","The last character on many eye codes: 1 right, 2 left, 3 both."],["Chapter 7","ICD-10-CM H00–H59, diseases of the eye and adnexa (the parts around the eye)."]],
  tips:["Before you call about a ‘routine not covered’ denial, look at the diagnosis on the claim. A Z01.00 on a medical claim is the whole story: it belongs to the vision plan.","Diabetes plus an eye exam is medical, once a year, even with no symptoms: Medicare covers a yearly diabetic retinopathy exam.","Codes change every 1 October. Check the code set in force on the date of service when a diagnosis is denied as invalid."],
  remember:"Z01.0- and H52 = routine = vision plan. H25 cataract, H40 glaucoma, E11.3 diabetic eye = medical plan. The diagnosis picks the payer.",
  see:[["basics","icd10"],["denial","Diagnosis invalid for date of service"]],
  source:SRC}
]},
{id:"vis-c",short:"Vision plans",title:"Who pays: vision plan or medical plan",blurb:"What a vision plan covers and what medical insurance covers, how vision benefits work, and coordination of benefits between the two.",lessons:[
 {id:"vis-plans",title:"Vision plans vs medical plans: who pays for what",
  keywords:["vision plan","vision insurance","medical vs vision","vision vs medical insurance","vision plan or medical plan","vsp","eyemed","davis vision","spectera","superior vision","avesis","routine vs medical","does medicare cover eye exams","medicare eye exam","medicare glasses","medicare vision","diabetic eye exam","glaucoma test medicare","which plan pays vision","vsp essential","vision benefit","routine exam","medical eye care"],
  line:"A vision plan (VSP, EyeMed, Davis Vision, Spectera, Superior Vision) pays for routine eye exams, glasses and contacts. Medical insurance (Medicare, Medicaid, commercial) pays for eye problems: infections, injuries, cataracts, glaucoma, diabetic eye disease. The diagnosis and the reason for the visit decide which one a claim goes to.",
  body:[
   "**Vision plans.** Usually a small benefit bought with the employer’s health plan or on its own. It covers a routine exam (often every 12 months), an allowance toward frames and lenses or contacts (often every 12 or 24 months), and set copays. Common names: VSP, EyeMed, Davis Vision, Spectera (UnitedHealthcare Vision), Superior Vision, Avesis, Humana Vision. Some, such as VSP, also sell an add-on for medical eye care (VSP’s Essential coverage) under which the vision plan pays for medical visits too.",
   "**Medical plans.** Original Medicare, Medicare Advantage, Medicaid and commercial plans pay for medical eye care: the red eye, the injury, cataract surgery, glaucoma monitoring, the yearly diabetic eye exam. They usually do **not** pay routine exams, refractions, glasses or contacts. Medicare Advantage and many Medicaid plans add a routine vision benefit, sometimes run by a vision vendor: check the card and the plan.",
   "**Which plan for this visit?** Ask three questions. Why did the patient come: a routine check or a problem? What did the doctor find and document: the diagnosis? What does each plan cover? A routine exam with a refractive error goes to the vision plan. A visit for a red, painful eye goes to the medical plan. A routine visit that finds a cataract can split: the exam may still be routine, while the follow-up for the cataract is medical.",
   "**Medicare and the eye.** Original Medicare does not cover routine eye exams, refractions or ordinary glasses. It does cover: a yearly eye exam for diabetic retinopathy; a glaucoma test every 12 months for people at high risk (diabetes, a family history of glaucoma, African Americans aged 50 or over, Hispanic Americans aged 65 or over); tests and treatment for macular degeneration; cataract surgery; and one pair of glasses or contacts after cataract surgery with an implanted lens. The patient pays 20% after the Part B deductible.",
   "**Why it matters.** Send a routine claim to the medical plan and it denies as routine or non-covered (often PR-96 with a Z01.00 diagnosis). Send a medical claim to the vision plan and it denies as not a covered benefit, or pays a routine exam that was really medical. Either way the claim ages and the patient gets the wrong bill."
  ],
  compare:{title:"Vision plan vs medical plan",head:["","Vision plan","Medical plan"],rows:[["Pays for","Routine exam, refraction, frames, lenses, contacts, CL fitting","Eye disease and injury: visits, tests, surgery, injections"],["Typical names","VSP, EyeMed, Davis Vision, Spectera, Superior Vision","Medicare, Medicaid, BCBS, UHC, Aetna, Cigna"],["Typical diagnosis","Z01.00/Z01.01, H52.-","H25 cataract, H40 glaucoma, E11.3 diabetic eye, H10 conjunctivitis"],["Typical codes","S0620/S0621 or 9200x, 92015, 92310, V codes","92002–92014 or 99202–99215, tests (92133, 92134, 92250), surgery"],["Benefit shape","Frequency (every 12 or 24 months), allowances, copays","Deductible, coinsurance, copay, medical necessity"],["Authorization","A benefit authorization pulled from the plan’s portal before the visit","Prior authorization for some procedures and injections"]]},
  terms:[["Vision plan","A benefit that covers routine eye care and materials; a separate payer from the medical plan, with its own ID and portal."],["Routine eye care","Care with no medical problem: a check-up, a prescription, glasses."],["Medical eye care","Care for an eye disease, injury or symptom; billed to medical insurance."],["VSP Essential","VSP’s add-on for medical eye care, where the vision plan also pays for medical visits (named on the card)."],["Vision vendor","A vision company that runs the routine vision benefit for a medical plan, such as a Medicare Advantage plan."]],
  tips:["Eligibility for an eye clinic is two checks: the medical plan and the vision plan. Both go on the account, and the EV note says which benefit applies to the visit.","Medicare patients can have both Medicare (medical) and a stand-alone vision plan for routine care. The denial ‘Vision plan vs medical plan: which pays first’ in the library walks through the order."],
  remember:"Routine exam, glasses, contacts → vision plan. Disease, injury, diabetes checks → medical plan. The diagnosis decides, not the patient’s preference.",
  see:[["denial","Vision plan vs. medical plan: which pays first"],["sop","vec-ev"]],
  source:SRC},
 {id:"vis-benefits",title:"Vision benefits: frequency, allowances, copays and authorizations",
  keywords:["vision benefits","benefit frequency","frames every 24 months","exam every 12 months","allowance","overage","vision copay","vsp authorization","eclaim","benefit authorization","vision eligibility","ev vision","last used date","benefit maximum vision","frequency denial","vision eligibility check","materials allowance","contact lens allowance"],
  line:"A vision plan pays by frequency (an exam every 12 months, frames every 24), by allowance (a fixed amount toward materials) and by copay. Before the visit, the eligibility check pulls the benefits and, for plans like VSP, a benefit authorization; a service outside the frequency or over the allowance is the patient’s.",
  body:[
   "**Frequency.** Every benefit has a clock: an exam once every 12 months, lenses every 12 months, frames every 24 months, contact lenses instead of glasses, are typical. The plan counts from the last date used, or by calendar year, plan by plan. A second exam inside the window denies as **benefit maximum reached** or frequency; the patient pays, if they were told beforehand.",
   "**Allowances and copays.** The exam usually has a copay (for example $10). Materials have an allowance (for example $150 toward frames, $130 toward contacts) and the patient pays the overage. Lens options (AR coating, progressives) may be covered, discounted or patient-paid. The benefit summary pulled before the visit is what the claim is measured against.",
   "**Authorizations.** Many vision plans want a benefit **authorization** pulled from their portal before the service. On VSP it is the eClaim authorization: it confirms eligibility and the benefits available on that date, and the claim must carry it. No authorization, no payment: the ‘authorization missing’ denial. This is different from a medical prior authorization: it takes minutes on the portal, and the eligibility (EV) team does it before the visit.",
   "**Eligibility verification for an eye visit** records, for the vision plan: the plan name and member ID, the exam, lens, frame and contact lens benefits with their frequency and last-used dates, the copays and allowances, and the authorization number. For the medical plan: copay, deductible and coinsurance for a medical visit. Purview’s VEC playbook shows the exact fields its EV team captures.",
   "**Family plans.** The subscriber’s vision plan covers dependents, and each dependent has their own benefit clock. Children often get polycarbonate lenses and more frequent replacements as a covered extra."
  ],
  compare:{title:"A typical vision benefit",head:["Benefit","Typical rule","If outside the rule"],rows:[["Exam","Once every 12 months, $10 copay","Denied: frequency / benefit maximum; the patient pays"],["Lenses","Once every 12 months, basic lens covered","The patient pays"],["Frames","Once every 24 months, $150 allowance","The patient pays the overage, or all of it outside the window"],["Contact lenses","$130 allowance instead of glasses","The patient pays the overage"],["CL fitting","Covered or discounted when contacts are chosen","The patient pays"],["Authorization","Pulled on the portal before the visit","Denied: authorization missing"]]},
  terms:[["Benefit frequency","How often a benefit can be used: every 12 months, every 24 months."],["Materials allowance","The amount the plan pays toward materials; the patient pays the rest."],["Benefit authorization","A vision plan’s confirmation, pulled before the visit, that the benefit is available; it goes on the claim."],["Benefit maximum","The benefit has been used for the period: the next one is the patient’s."],["EV for an eye visit","Eligibility verification: the check of medical and vision coverage done before the visit."]],
  tips:["The last-used date is the key fact. An exam used on 10 March can be used again from 10 March next year, or from 1 January if the plan runs by calendar year; check which.","Pull the authorization before the visit, not after: many plans will not backdate it."],
  remember:"Frequency, allowance, copay, authorization. Check all four before the visit; after the visit it is too late to change the answer.",
  see:[["sop","vec-ev"],["denial","Vision benefit not eligible: exam or materials"]],
  source:SRC},
 {id:"vis-cob",title:"COB in vision: medical first for medical problems, then the vision plan",
  keywords:["vision cob","cob vision","vision secondary","medical first vision","vsp secondary","eyemed cob","davis vision cob","who pays first vision","medical or vision first","co-22 vision","covered by another payer vision","eob vision secondary","vision plan secondary","coordination of benefits vision"],
  line:"When a patient has a medical plan and a vision plan they are not primary and secondary in the usual sense: each covers different things. A medical diagnosis goes to the medical plan first; routine care goes to the vision plan. When both could pay, bill the medical plan first and send the vision plan the medical EOB, if that vision plan coordinates at all.",
  body:[
   "**Two plans, two jobs.** Most of the time there is no COB question: the routine exam belongs to the vision plan and the medical visit to the medical plan. COB arises when one service could fall under both, for example a comprehensive exam with a medical diagnosis for a patient whose vision plan also covers medical exams (VSP Essential, or a medical eye care rider).",
   "**Medical first.** With a medical diagnosis, bill the medical plan first. What it leaves to the patient (deductible, coinsurance, a non-covered refraction) can then go to the vision plan as secondary, with the medical EOB attached, where the vision plan coordinates benefits. Plans differ: VSP coordinates on its medical coverage; EyeMed and Davis Vision generally do not coordinate on routine benefits, so the balance after the medical plan is the patient’s (less any refraction the clinic adjusts by its own rule).",
   "**Two medical plans, or Medicare plus a plan.** The ordinary COB rules apply: the Medicare Secondary Payer rules, the birthday rule for children, the subscriber-before-dependent rule. The denial ‘Vision plan vs medical plan: which pays first’ in the library works through the common cases, and the RCM Basics COB module has the general rules.",
   "**The denial you will see.** CO-22 or ‘covered by another payer’ on a vision claim usually means the plan thinks a medical plan should see the claim first, or that another vision plan is on file. Check the diagnosis, check which plans are active and in what order, and bill the right one first."
  ],
  compare:{title:"Who pays first",head:["Situation","First","Then"],rows:[["Routine exam, refractive error only","Vision plan","Patient copay and overage"],["Medical problem visit (red eye, glaucoma check)","Medical plan","Patient’s deductible or coinsurance; vision plan secondary only if it coordinates"],["Routine exam that finds a cataract","Vision plan for the routine exam; the cataract work-up is medical","Patient per each plan"],["Diabetic patient’s yearly eye exam","Medical plan (Medicare covers it)","Patient 20%; a Medigap or secondary plan"],["Medicare patient, routine exam and glasses","Stand-alone vision plan if there is one","Patient; Medicare does not pay routine care"],["Post-cataract glasses, Medicare","Medicare (DME MAC), one pair","Patient 20%"]]},
  terms:[["Vision COB","Coordination of benefits between a medical plan and a vision plan: which pays first and what the second one considers."],["Medical first","With a medical diagnosis, the medical plan sees the claim before any vision plan."],["Coordinating vision plan","A vision plan that pays as secondary after a medical EOB; many routine vision benefits do not."]],
  tips:["Attach the medical EOB when you bill a vision plan as secondary; without it the claim comes back as ‘primary EOB required’.","Do not bill the vision plan ‘to see if it pays’ after the medical plan paid in full. Two payments for one service is a credit balance to refund."],
  remember:"Medical diagnosis → medical plan first. Routine → vision plan. Secondary only where the vision plan coordinates, and always with the EOB.",
  see:[["denial","Vision plan vs. medical plan: which pays first"],["basics","cob"],["sop","vec-cob"]],
  source:SRC}
]},
{id:"vis-d",short:"Vision denials",title:"Working vision claims and denials",blurb:"The eight denials vision billers see most, the not-on-file claim and timely filing, and what makes a vision claim stand up.",lessons:[
 {id:"vis-denials",title:"The common vision denials and the first thing to check",
  keywords:["vision denials","common vision denials","routine not covered","routine eye exam denied","eye exam denied","routine exam denied","routine denied","vision denial reasons","why was the exam denied","z dx denial","zdx denial","pr-96 vision","vision claim denied","authorization missing vision","maximum benefit vision","frequency denial","provider not on panel","dx issue","level of care","what to do when a vision claim is denied","refraction denied","refraction not covered","why was the eye exam denied","why was the routine eye exam denied"],
  line:"Most vision denials are one of eight: routine or Z diagnosis not covered, authorization missing, benefit maximum or frequency, COB, eligibility or demographics, provider not on the panel, diagnosis mismatch, and medical necessity or level of care. Each has one first check, and most are prevented before the visit.",
  compare:{title:"The eight denials",head:["Denial","What it means","First check","Usual fix"],rows:[
   ["Routine code / Z dx non-covered","The medical plan does not pay routine care","The diagnosis and the plan: Z01.00 or H52 on a medical claim?","Bill the vision plan; if there is none, the patient (refraction is patient-paid)"],
   ["Authorization missing","No benefit authorization (vision) or prior auth (medical) on file","The plan portal for an authorization on the DOS","Pull or request it; corrected claim with the number"],
   ["Maximum benefit / frequency","The exam or materials benefit was used in the period","The last-used date in the plan’s benefit summary","Patient responsibility if they were told; otherwise ask the practice"],
   ["COB","The plan thinks another payer should pay first","Active plans on the DOS and the diagnosis","Bill the right plan first; send the EOB to the second"],
   ["Eligibility / demographic","Name, DOB or ID do not match the plan, or no coverage on the DOS","The card, the ID, the DOB and the eligibility response","Correct and resubmit, or bill the active plan"],
   ["Provider-related","The provider is not on the vision plan’s panel, or the NPI or taxonomy is wrong","Panel status and the rendering NPI","Corrected claim, or the practice’s out-of-network rule"],
   ["Dx issue","Diagnosis missing, invalid, or does not fit the service","The chart against the claim; the code set in force on the DOS","Corrected claim after coding review"],
   ["Level of care / medical necessity","The service was not medically necessary at that level","The documentation and the plan’s policy","Appeal with records, or adjust by the client’s rule"]]},
  body:[
   "**What we do when a claim denies.** Review the coverage and benefits for the DOS; get the authorization if it was missing; correct the claim if a code was wrong; appeal or ask for reconsideration where the denial is wrong; check COB; and, only when the plan truly does not cover it and the patient was responsible, bill the patient. Every step goes in the note.",
   "**Refraction.** The small line that denies most often. Medicare and many medical plans do not cover 92015. The clinic either collects it from the patient at the visit, bills it to the vision plan, or adjusts it by the client’s rule (the VEC playbook adjusts the refraction on COB claims). Know your client’s rule before you touch it.",
   "**Prevent before you chase.** Eligibility before the visit, the authorization pulled, the right plan on the account, the diagnosis matched to the visit type: these stop most vision denials. AR’s job on the ones that slip through is to find which check was missed and feed it back."
  ],
  terms:[["Z dx denial","A routine diagnosis (Z01.0-) billed to a medical plan: routine care is not covered."],["Panel (vision plan network)","The vision plan’s network; a provider not on it is out of network."],["Reconsideration (vision plan)","Asking the plan to look again, with the facts; an appeal is the formal version with documents."]],
  tips:["Read the remark code with the reason code: PR-96 with N130 (consult plan benefit documents) says non-covered benefit; CO-197 says authorization; CO-22 says another payer.","A denial on a routine claim is often a bill for the patient, but only after the practice’s rule and the benefit summary say so. Never move a balance to the patient without that check."],
  remember:"Eight denials, one first check each. Routine → wrong plan? Auth → pulled? Frequency → last used? COB → order? Eligibility → match? Provider → panel? Dx → fits? Necessity → records?",
  see:[["denial","Vision benefit not eligible: exam or materials"],["denial","Vision plan vs. medical plan: which pays first"],["sop","vec-pr96"]],
  source:SRC},
 {id:"vis-nof",title:"Not on file: resubmission and timely filing on a vision plan",
  keywords:["not on file vision","claim not on file vsp","resubmit vision claim","vision timely filing","vsp timely filing","eyemed timely filing","tfl vision plan","resubmission vision","clearinghouse acceptance","proof of timely filing vision","vsp portal","eyemed portal","vision claim status"],
  line:"A vision claim that the plan says it never received is resubmitted inside the plan’s filing limit, after a check that it really was not received: the clearinghouse acceptance, the portal, or a call. Each vision plan sets its own limit, so check the plan’s manual and the client’s playbook before you count the days.",
  flow:{steps:["Check the clearinghouse for the acceptance date","Check the plan’s portal for the claim status","Call the plan if the portal shows nothing","Rejected or never sent: fix the error and send it as a new claim","Received and denied: a corrected claim or an appeal, not a resubmission","Count the filing limit from the DOS by the plan’s rule; past it, attach proof of timely filing","Note the source, the date, the reference and the follow-up"],to:"The claim is on file and in process"},
  body:[
   "**Was it received?** Start with the clearinghouse: an acceptance report proves the claim reached the plan and when. Then the plan’s portal (VSP’s, EyeMed’s) for the claim status. Only then call. ‘Not on file’ at the plan with an acceptance at the clearinghouse is a plan-side problem, and the acceptance report is your proof of timely filing.",
   "**Fix, then resubmit.** If the claim was rejected on the way (a wrong member ID, no authorization number, a missing diagnosis), correct it and send it again as a new claim; a rejection never reached the plan, so it is not a corrected claim. If the plan had it and denied it, that is a corrected claim or an appeal instead.",
   "**Timely filing.** Vision plans count their filing limit from the date of service like other payers. The limits vary by plan and by contract (several run from 180 days to a year), so confirm the figure in the plan’s provider manual or the client’s playbook rather than from memory. Past the limit, the claim needs proof of timely filing (the acceptance report) or it is a write-off by the client’s rule, never a bill to the patient.",
   "**Document the status.** Note where you checked and what it said: ‘Clearinghouse accepted 12 March; VSP portal shows not on file; call ref ___; resubmitted 20 March with auth ___; follow up 7 days.’ The next person can act on that note. ‘Resubmitted’ alone helps no one."
  ],
  terms:[["Not on file (vision plan)","The plan has no record of the claim: it was never sent, rejected before arrival, or lost."],["Acceptance report","The clearinghouse’s proof that the payer took the claim, with the date."],["Vision plan filing limit","The plan’s deadline for the first claim, counted from the date of service; it varies plan by plan."],["Rejection vs denial on a vision plan","A rejection never entered the plan’s system; a denial was processed and refused."]],
  tips:["Vision plan portals are quick: VSP and EyeMed show claim status within days. Check there before you call.","Follow-up on a vision plan is faster than on a medical plan: the VEC playbook rechecks a vision claim in process in 7 days and a medical one in 20."],
  remember:"Prove it was received before you resubmit. Rejected → fix and resend. Denied → correct or appeal. Count the limit from the DOS, by the plan’s rule.",
  see:[["denial","No claim on file"],["sop","vec-nof"]],
  source:SRC},
 {id:"vis-justify",title:"Justifying the claim: diagnosis, necessity, documentation and compliance",
  keywords:["justify the claim","justifying the claim","medical necessity vision","documentation vision claim","compliance vision","four rights","retinal imaging code","92250","92133","92134","oct code","fundus photography","records request vision","audit vision claim","big picture vision rcm","right service right code"],
  line:"A claim is paid when the plan believes the service was needed and really happened: an accurate diagnosis, medical necessity where the plan requires it, documentation in the chart that supports every line, and compliance with HIPAA, the payer’s rules and the coding guidelines. Right service, right code, right paperwork, right payer order.",
  body:[
   "**Accurate diagnosis.** The ICD-10 code must match what the doctor found and wrote. A routine Z code on a visit the chart calls a glaucoma check, or a cataract code added to get a medical plan to pay a routine exam, is wrong in both directions: the first loses money, the second is fraud.",
   "**Medical necessity.** Medical plans pay for care that is needed: the symptom, the finding, the test that follows from it. Tests such as retinal imaging (92250, fundus photography) or OCT (92133, 92134) need a diagnosis that justifies them; a screening photo on a healthy eye is the patient’s, or the vision plan’s where it has a retinal imaging benefit.",
   "**Supporting documentation.** History, exam findings, the refraction result, test results, the plan and the prescription. Missing refraction values are a known cause of S0621 denials on audit; a fitting fee with no fitting notes will not survive a records request.",
   "**Compliance.** HIPAA on every call and note (two identifiers, minimum necessary); the payer’s billing guide; CPT, HCPCS and ICD-10 guidelines; and the client’s own rules. Never choose a code because it pays. Never bill a patient a plan’s write-off. Never add a diagnosis that is not in the chart.",
   "**The big picture.** Good vision RCM is four things done right: the right service (exam, refraction, CL, CL fitting, materials), the right codes (CPT or S for the service, V for materials, ICD-10 for the reason), the right paperwork (eligibility, authorization, documentation, COB) and the right payer order (vision or medical, primary then secondary). Get all four right and the claim pays the first time."
  ],
  compare:{title:"The four rights",head:["Right","Means","If wrong"],rows:[["Right service","Bill what was done and documented, each service on its own line","Missing or unbundled lines; audit risk"],["Right code","CPT or S for the exam, V for materials, ICD-10 that matches","Dx mismatch, downcode, denial"],["Right paperwork","Eligibility, authorization, documentation, COB","Auth missing, records request, COB denial"],["Right payer order","Vision or medical, primary before secondary","Routine non-covered, CO-22, primary EOB required"]]},
  terms:[["Medical necessity for eye tests","The test was needed for the diagnosis, and the chart shows why."],["Fundus photography (92250) / OCT (92133, 92134)","Common eye tests that need a supporting medical diagnosis."],["Compliance on a vision claim","Following HIPAA, the plan’s rules and the coding guidelines so the claim is accurate and honest."]],
  tips:["If a code or a diagnosis looks chosen to make a claim pay rather than to describe the visit, stop and ask your supervisor. It is a compliance question, not a billing one.","On a records request, send the exam note, the test results and the prescription: the plan is checking that the lines on the claim appear in the chart."],
  remember:"Right service + right code + right paperwork + right payer order = paid the first time. A diagnosis is a fact from the chart, never a tool.",
  see:[["basics","hipaa"]],
  source:SRC}
]}
]});

/* Assessment questions: t = module short. Each wrong option carries its own "why not" (whyNot, in order). */
const Q=[
/* Vision basics */
{t:"Vision basics",q:"Which eye professional performs cataract surgery?",correct:"An ophthalmologist (MD or DO)",wrongs:["An optometrist (OD)","An optician","Any provider on the vision plan’s panel"],whyNot:["Optometrists examine eyes and prescribe; they do not operate.","Opticians fit and dispense glasses; they are not doctors.","Being on a panel says nothing about the profession. Surgery is the ophthalmologist’s work."],ex:"Ophthalmologists are medical doctors trained in eye disease and surgery. Optometrists do everyday eye care; opticians dispense."},
{t:"Vision basics",q:"Most routine vision claims (exam, refraction, glasses) come from:",correct:"Optometrists",wrongs:["Ophthalmologists","Opticians","Hospitals"],whyNot:["Ophthalmologists mostly bill medical eye care: disease, tests and surgery.","Opticians dispense glasses; they do not examine or bill exams.","Routine eye care happens in clinics, not hospitals."],ex:"The optometrist is the family eye doctor: exams, prescriptions and the materials that follow."},
{t:"Vision basics",q:"The optician’s work appears on a claim as:",correct:"Materials: frames, lenses and contact lenses (V codes)",wrongs:["The exam code","The refraction","The rendering provider’s NPI"],whyNot:["The exam is the doctor’s work, billed under the doctor.","The refraction is a test the doctor does.","The rendering provider is the doctor who saw the patient, never the optician."],ex:"The optician fills the prescription: frames, lenses and fitting the glasses. On the claim that is the materials side."},
{t:"Vision basics",q:"A patient comes for a check-up, the doctor finds the glasses power, and the patient chooses contact lenses, which the doctor checks for fit. How many separate services is that?",correct:"Four: exam, refraction, contact lens evaluation and CL fitting",wrongs:["One: it is all the eye exam","Two: the exam and the glasses","Three: the exam, the refraction and the contacts"],whyNot:["Each step is its own service with its own code, not one exam.","No glasses were made here, and the refraction and the contact lens work are separate services.","The contact lens evaluation and the fitting are two services, not one."],ex:"Exam → check. Refraction → prescription. CL → contact lens. CL fitting → proper fit. Four services, four lines."},
{t:"Vision basics",q:"‘Refraction’ means:",correct:"Finding the exact lens power the patient needs",wrongs:["Checking the health of the retina","Fitting a contact lens","Handing over the finished glasses"],whyNot:["Checking eye health is the exam.","Fitting a lens is CL fitting.","Handing over the glasses is dispensing."],ex:"Refraction finds the prescription: for example right eye −2.00, left eye −1.50. It is billed as 92015."},
{t:"Vision basics",q:"A contact lens fitting is complete when:",correct:"The lens sits right, is comfortable, gives clear vision and moves properly when the patient blinks",wrongs:["The patient has paid for the lenses","The refraction is done","The frame has been adjusted"],whyNot:["Payment is a billing step, not part of the fitting.","The refraction finds the power; the fitting checks the lens on the eye.","Frames belong to glasses, not contact lenses."],ex:"The doctor checks position, comfort, clarity and movement on a blink. When all four are right, the fitting is done."},
{t:"Vision basics",q:"In the shoe-shop picture, the shop tells you your exact size. In eye care that is:",correct:"Refraction",wrongs:["The exam","CL","CL fitting"],whyNot:["Checking the foot size is the exam.","Choosing a special shoe is CL.","Making sure the shoe is comfortable when you walk is CL fitting."],ex:"Check the foot (exam), tell the size (refraction), choose a special shoe (CL), make sure it fits (CL fitting)."},
{t:"Vision basics",q:"A patient sees near objects clearly but far objects are blurry. The condition and the lens:",correct:"Myopia; a minus lens",wrongs:["Hyperopia; a plus lens","Presbyopia; a reading add","Astigmatism; a cylinder"],whyNot:["Hyperopia is the opposite: far is clearer than near.","Presbyopia is near focus fading with age.","Astigmatism blurs vision at all distances."],ex:"My-opia: my close vision is fine, far is blurry. Light focuses in front of the retina; a minus lens (−2.00) pushes the image back."},
{t:"Vision basics",q:"Light focusing behind the retina is:",correct:"Hyperopia (farsightedness)",wrongs:["Myopia","Astigmatism","Glaucoma"],whyNot:["In myopia light focuses in front of the retina.","Astigmatism is an uneven curve, not a focus behind the retina.","Glaucoma is an eye disease (pressure and nerve damage), not a refractive error."],ex:"Hyperopia, also called hypermetropia: far things are clearer than near. A plus lens pulls the image forward."},
{t:"Vision basics",q:"A 45-year-old whose near focus is fading needs:",correct:"A reading add: bifocals, progressives or multifocal contacts (presbyopia)",wrongs:["A stronger minus lens (myopia)","A toric lens (astigmatism)","Cataract surgery"],whyNot:["A minus lens is for distance blur from myopia, not age-related near blur.","A toric lens corrects astigmatism.","Presbyopia is normal ageing of the lens, not a cataract."],ex:"Presbyopia starts around 40: the eye’s lens stiffens and near focus fades. The fix is extra near power."},
{t:"Vision basics",q:"On a prescription, OD and OS mean:",correct:"Right eye and left eye",wrongs:["Both eyes and one eye","Distance and near","Optometrist and ophthalmologist"],whyNot:["OU means both eyes.","Distance and near are the sphere and the add, not OD and OS.","OD is also short for Doctor of Optometry, but on a prescription it is the right eye."],ex:"OD right, OS left, OU both. Sphere, cylinder, axis and add are the powers."},
{t:"Vision basics",q:"A materials claim shows +2.00 lenses with a myopia diagnosis. You:",correct:"Ask before sending it: myopia takes a minus lens, so something does not add up",wrongs:["Send it: the plan does not check powers","Change the diagnosis to hyperopia","Change the lens power to −2.00"],whyNot:["A claim that contradicts itself invites a denial or an audit.","A biller never changes a diagnosis; it comes from the chart.","A biller never changes clinical values; ask the practice."],ex:"Minus for myopia, plus for hyperopia. A mismatch is a question for the practice, not a correction you make."},
/* Vision codes */
{t:"Vision codes",q:"92014 is:",correct:"A comprehensive eye exam, established patient",wrongs:["A comprehensive eye exam, new patient","An intermediate eye exam, new patient","Refraction"],whyNot:["The new patient comprehensive exam is 92004.","The new patient intermediate exam is 92002.","Refraction is 92015."],ex:"9200x new, 9201x established; 2 intermediate, 4 comprehensive."},
{t:"Vision codes",q:"A patient last seen by the practice two years ago comes for a comprehensive exam. The code:",correct:"92014 (established)",wrongs:["92004 (new)","92002","S0620"],whyNot:["Seen within three years means established, so a new patient code is wrong.","92002 is an intermediate exam for a new patient.","S0620 is a routine exam for a new patient."],ex:"Within three years, same practice: established. 92014 is the established comprehensive exam."},
{t:"Vision codes",q:"Refraction is billed as:",correct:"92015 on its own line",wrongs:["Part of 92014","V2020","99213"],whyNot:["The eye exam codes do not include the refraction.","V2020 is a frame.","99213 is an office visit E/M code."],ex:"92015 is always its own line, and Original Medicare does not cover it."},
{t:"Vision codes",q:"Which payer never pays S0620 / S0621?",correct:"Original Medicare",wrongs:["VSP","A Medicaid plan","A commercial vision plan"],whyNot:["Vision plans such as VSP commonly use the S codes for routine exams.","Many Medicaid plans accept the S codes.","Commercial vision plans commonly use them."],ex:"S codes are HCPCS Level II codes for commercial and Medicaid plans. Medicare does not recognise them."},
{t:"Vision codes",q:"A vision plan asks for S0621 for routine exams. You also bill 92015. The result:",correct:"92015 denies: the refraction is already inside S0621",wrongs:["Both pay","S0621 denies","The plan pays 92015 at 50%"],whyNot:["The S code already includes the refraction, so 92015 is a duplicate.","S0621 is the code the plan asked for; it is the extra line that fails.","Plans do not half-pay a duplicate line; they deny it."],ex:"S0620/S0621 mean a routine exam including refraction. Never bill 92015 with them."},
{t:"Vision codes",q:"The standard contact lens fitting code for both eyes is:",correct:"92310",wrongs:["92311","92072","V2520"],whyNot:["92311 is a fitting for one aphakic eye.","92072 is the initial fitting for keratoconus.","V2520 is a contact lens itself (materials), not the fitting."],ex:"92310: fitting of corneal contact lenses, both eyes, no aphakia. The lenses are V25xx."},
{t:"Vision codes",q:"A contact lens fitting for keratoconus is coded:",correct:"92072, to the medical plan",wrongs:["92310","S0592","V2500"],whyNot:["92310 with a keratoconus diagnosis is a coding error that denies.","S0592 is a routine contact lens evaluation on some vision plans.","V2500 is a lens (materials), not a fitting."],ex:"92072 is the initial keratoconus fitting, a medical service with the H18.6- diagnosis."},
{t:"Vision codes",q:"Which of these is a materials code?",correct:"V2020, a frame",wrongs:["92310","S0620","Z01.00"],whyNot:["92310 is the contact lens fitting service.","S0620 is a routine exam code.","Z01.00 is a diagnosis code."],ex:"Materials are HCPCS V codes: frames, lenses and contact lenses."},
{t:"Vision codes",q:"A pair of single-vision lenses is billed as:",correct:"Two units of the lens code, one per lens",wrongs:["One unit","One frame code","92015"],whyNot:["Lens codes are per lens, so a pair is two units.","The frame is a separate code, V2020.","92015 is the refraction, not the lenses."],ex:"Per lens means two units for a pair. The frame is one unit of V2020."},
{t:"Vision codes",q:"Anti-reflective coating is:",correct:"V2750, per lens",wrongs:["V2744","V2781","V2784"],whyNot:["V2744 is a photochromic tint.","V2781 is a progressive lens.","V2784 is a polycarbonate lens."],ex:"V2750 AR coating, V2755 UV, V2744 photochromic, V2781 progressive, V2784 polycarbonate: all per lens."},
{t:"Vision codes",q:"Z01.00 on a claim means:",correct:"A routine eye exam with no abnormal findings",wrongs:["Cataract","Glaucoma","Diabetic eye disease"],whyNot:["Cataract is H25 or H26.","Glaucoma is H40.","Diabetic eye disease is E11.3- (type 2)."],ex:"Z01.00 and Z01.01 are the routine eye exam codes. On a medical claim they are the ‘Z dx’ denial."},
{t:"Vision codes",q:"A comprehensive exam carries the diagnosis H40.11X3 (glaucoma). The claim goes to:",correct:"The medical plan: glaucoma is a medical diagnosis",wrongs:["The vision plan","The patient","The DME MAC"],whyNot:["Vision plans cover routine care; glaucoma is disease.","Insurance is billed before the patient, and this is covered medical care.","The DME MAC pays post-cataract glasses, not exams."],ex:"The diagnosis picks the payer. H40 glaucoma is medical, even at an optometrist."},
{t:"Vision codes",q:"Which diagnosis makes a visit routine?",correct:"H52.1- myopia",wrongs:["E11.3- diabetic eye disease","H25.- cataract","H10.- conjunctivitis"],whyNot:["Diabetic eye disease is medical.","Cataract is medical.","Conjunctivitis (pink eye) is medical."],ex:"H52 refractive errors and Z01.0- are routine, vision plan business. Disease codes are medical."},
/* Vision plans */
{t:"Vision plans",q:"A patient comes in with a red, painful eye. The claim goes to:",correct:"The medical plan",wrongs:["The vision plan","Both plans at once","The patient"],whyNot:["A symptom is medical eye care, not a routine benefit.","Claims go to one payer first, never both at once.","Covered medical care is billed to insurance before the patient."],ex:"Routine exam, glasses, contacts → vision plan. Disease, injury, symptoms → medical plan."},
{t:"Vision plans",q:"Original Medicare covers:",correct:"A yearly eye exam for diabetic retinopathy",wrongs:["Routine eye exams","Refraction","Ordinary glasses every two years"],whyNot:["Medicare does not cover routine eye exams.","Medicare does not cover refraction (92015).","Medicare covers glasses only once, after cataract surgery with an implant."],ex:"Medicare pays for medical eye care: the diabetic eye exam, glaucoma tests for high-risk patients, cataract surgery. Not routine care."},
{t:"Vision plans",q:"After cataract surgery with a lens implant, Medicare pays for:",correct:"One pair of glasses or contact lenses, billed to the DME MAC",wrongs:["New glasses every year","Nothing: glasses are never covered","A yearly routine exam"],whyNot:["It is one pair after the surgery, not a yearly benefit.","This is the one exception to the no-glasses rule.","Routine exams are not covered by Original Medicare."],ex:"The post-cataract pair is Medicare’s one glasses benefit. It goes to the DME MAC with the V codes."},
{t:"Vision plans",q:"VSP, EyeMed and Davis Vision are:",correct:"Vision plans that cover routine exams and materials",wrongs:["Medical plans","Medicare contractors","Clearinghouses"],whyNot:["Medical plans are Medicare, Medicaid, BCBS, UHC and the like.","Medicare contractors (MACs) process Medicare claims.","Clearinghouses pass claims to payers; they do not pay."],ex:"Vision plans are separate payers with their own IDs and portals, for routine exams, frames, lenses and contacts."},
{t:"Vision plans",q:"A routine exam with a Z01.00 diagnosis is sent to the patient’s medical plan. Expect:",correct:"A routine / non-covered denial; the vision plan should have been billed",wrongs:["Payment at 80%","A request for an authorization","A duplicate denial"],whyNot:["Medical plans do not pay routine exams.","No authorization makes routine care covered by a medical plan.","Nothing was billed twice."],ex:"Z01.00 on a medical claim is the ‘Z dx’ denial. Bill the vision plan."},
{t:"Vision plans",q:"A vision plan allows frames every 24 months and the last frames were 18 months ago. New frames today are:",correct:"The patient’s: the benefit is not available yet",wrongs:["Covered","Covered at half the allowance","Covered if the patient has a medical diagnosis"],whyNot:["The 24-month clock has not run out.","Plans do not half-pay an unavailable benefit.","A medical diagnosis does not change a materials frequency rule."],ex:"Frequency is a clock from the last-used date. Inside the window, the benefit is used up."},
{t:"Vision plans",q:"The frame allowance is $150 and the frame costs $220. The patient owes:",correct:"The $70 overage, plus any copay",wrongs:["Nothing","$150","$220"],whyNot:["The allowance covers only $150 of the $220.","$150 is the plan’s share.","The plan pays $150 of it."],ex:"The plan pays its allowance; the overage above it is the patient’s by the plan’s own rules."},
{t:"Vision plans",q:"A VSP benefit authorization is:",correct:"Pulled from the plan’s portal before the visit and carried on the claim",wrongs:["A medical prior authorization requested by the doctor","The patient’s signature on the claim","Needed only for surgery"],whyNot:["It is a benefit check on the portal, not a clinical approval.","It is the plan’s confirmation, not the patient’s signature.","It is needed for routine exams and materials."],ex:"No authorization, no payment. The EV team pulls it before the visit."},
{t:"Vision plans",q:"Who pays first for a diabetic patient’s yearly eye exam?",correct:"The medical plan (Medicare covers it)",wrongs:["The vision plan","The patient","The DME MAC"],whyNot:["Diabetes makes the exam medical, not routine.","Covered care is billed to insurance before the patient.","The DME MAC pays equipment and post-cataract glasses, not exams."],ex:"Medicare covers one diabetic retinopathy exam a year. It is a medical claim."},
{t:"Vision plans",q:"A medical plan paid an exam and left $40 coinsurance. The patient’s vision plan coordinates benefits. You:",correct:"Bill the vision plan as secondary with the medical EOB attached",wrongs:["Bill the patient $40 straight away","Bill the vision plan as primary","Write off the $40"],whyNot:["A coordinating vision plan may pay the $40; bill it before the patient.","The medical plan has already paid as primary.","Nothing says the $40 is a write-off."],ex:"Medical first. Then the vision plan as secondary, with the EOB, where it coordinates."},
{t:"Vision plans",q:"‘Medical first’ in vision COB means:",correct:"With a medical diagnosis, the medical plan sees the claim before any vision plan",wrongs:["The medical plan pays all vision care","Medicare pays before every other plan","The patient pays first"],whyNot:["Medical plans do not pay routine vision care.","Medicare is often secondary, under the MSP rules.","Insurance is billed before the patient."],ex:"Medical diagnosis → medical plan first. Routine → vision plan. Secondary only where the vision plan coordinates."},
/* Vision denials */
{t:"Vision denials",q:"The first check on a ‘routine code / Z dx non-covered’ denial:",correct:"Which diagnosis and which plan: a Z01.00 on a medical claim belongs to the vision plan",wrongs:["The patient’s payment history","The frame price","The provider’s NPI"],whyNot:["Payment history does not explain a routine denial.","The frame price is a materials question, not this denial.","The NPI matters for provider denials, not routine ones."],ex:"Routine care is not covered by medical plans. Check the diagnosis, then bill the vision plan."},
{t:"Vision denials",q:"A vision claim denied for a missing authorization. First:",correct:"Check the plan’s portal for an authorization on the DOS and add it to a corrected claim",wrongs:["Bill the patient","Write it off","Appeal with medical records"],whyNot:["A missing authorization is never the patient’s to pay.","The authorization may exist; check before writing anything off.","Records do not fix a missing authorization number."],ex:"Pull or request the authorization, then send the corrected claim with the number."},
{t:"Vision denials",q:"‘Maximum benefit reached’ on a routine exam means:",correct:"The exam benefit was used earlier in the period",wrongs:["The plan has closed the patient’s policy","The provider is not on the panel","The claim was filed late"],whyNot:["The policy is active; one benefit is used up.","Panel problems deny as provider-related.","Late claims deny as timely filing."],ex:"Frequency: the last-used date in the benefit summary tells you when it is available again."},
{t:"Vision denials",q:"A denial says the provider is not on the plan’s panel, but the provider is in network with Blue Cross. This is:",correct:"Possible: vision plans credential providers separately from medical plans",wrongs:["Impossible","A duplicate denial","A COB issue"],whyNot:["Medical network status says nothing about a vision plan’s panel.","Nothing was billed twice.","COB is about payer order, not network status."],ex:"Check the vision plan’s panel before the visit, not the medical network."},
{t:"Vision denials",q:"Refraction (92015) is denied by Medicare. You:",correct:"Follow the client’s rule: it is non-covered, so patient responsibility or an adjustment, never an appeal",wrongs:["Appeal with records","Rebill it as 92014","Bill the DME MAC"],whyNot:["Medicare does not cover refraction; an appeal cannot change that.","Rebilling a test as an exam is a false claim.","The DME MAC pays equipment, not refractions."],ex:"Refraction is the line that denies most often. The clinic collects it, bills the vision plan, or adjusts it by its rule."},
{t:"Vision denials",q:"The plan says a claim is ‘not on file’. First:",correct:"Check the clearinghouse acceptance report, then the plan’s portal",wrongs:["Resubmit at once","Bill the patient","Appeal"],whyNot:["Resubmitting a claim the plan already has makes a duplicate.","A missing claim is not the patient’s fault.","There is nothing to appeal until the claim is on file."],ex:"Prove whether it was received before you resubmit. The acceptance report is also your proof of timely filing."},
{t:"Vision denials",q:"The plan never received the claim because it was rejected for a wrong member ID. You:",correct:"Fix the ID and send it as a new claim",wrongs:["Send a corrected claim with frequency code 7","Appeal","Adjust it as timely filing"],whyNot:["A rejection never reached the plan, so there is nothing to correct on its side.","There is no denial to appeal.","Timely filing applies only once the limit has passed."],ex:"Rejected → fix and resend as new. Denied → corrected claim or appeal."},
{t:"Vision denials",q:"A vision plan’s timely filing limit is counted from:",correct:"The date of service, by the plan’s own rule",wrongs:["The denial date","The day the patient paid the copay","The end of the calendar year"],whyNot:["The denial date starts the appeal clock, not the filing limit.","The copay date plays no part.","Filing limits run from the DOS, not the year end."],ex:"Limits vary by plan and contract. Check the plan’s manual and the client’s playbook, and count from the DOS."},
{t:"Vision denials",q:"A vision claim is past the filing limit, and the clearinghouse shows it was accepted in time. You:",correct:"Resubmit with the acceptance report as proof of timely filing",wrongs:["Write it off","Bill the patient","Change the date of service"],whyNot:["There is proof it was filed in time; the claim can be paid.","A timely filing problem is never the patient’s to pay.","Changing a DOS is fraud."],ex:"The acceptance report proves the original filing date."},
{t:"Vision denials",q:"A cataract diagnosis is added to a routine exam so the medical plan will pay it. This is:",correct:"Fraud: diagnoses come from the chart, never from the payer you want",wrongs:["Smart billing","Allowed if the patient agrees","A coding preference"],whyNot:["Billing a diagnosis the doctor did not document is a false claim.","The patient cannot authorise a false diagnosis.","It is not a preference; it is a false claim."],ex:"A diagnosis is a fact from the chart, never a tool. Ask your supervisor when something looks chosen to make a claim pay."},
{t:"Vision denials",q:"Retinal photography (92250) on a healthy eye with no medical diagnosis is:",correct:"Not medically necessary for the medical plan: patient-paid, or a vision plan screening benefit",wrongs:["Always covered by Medicare","Billed to the DME MAC","Part of the refraction"],whyNot:["Medicare pays tests that a medical diagnosis justifies, not screenings on healthy eyes.","The DME MAC pays equipment, not tests.","Retinal photography is its own test, not part of 92015."],ex:"Tests need a diagnosis that justifies them. A screening photo belongs to the patient or a vision plan benefit."},
{t:"Vision denials",q:"The ‘four rights’ of vision RCM are:",correct:"Right service, right code, right paperwork, right payer order",wrongs:["Right doctor, right price, right time, right place","Right frame, right lens, right coating, right PD","Right CPT, right ICD, right NPI, right TIN"],whyNot:["Those are not the four rights in the guide.","Those are materials choices, not the claim’s four rights.","Codes and identifiers are part of ‘right code’; paperwork and payer order are missing."],ex:"Right service + right code + right paperwork + right payer order = paid the first time."}
];
Q.forEach(x=>{ x.c="vision"; SPEC_QUIZ.push(x); });
})();
